-- Muhammad Asim — Portfolio database: schema + RLS + seed data
-- Generated by scripts/generate-migration.mjs — safe to re-run (idempotent).
-- Apply via: Supabase dashboard → SQL Editor (paste & run)
--        or: node scripts/setup-database.mjs
-- Contains NO secrets. Admin user is bootstrapped separately by the setup script.

create table if not exists public.site_settings (
  key text primary key,
  value jsonb not null,
  updated_at timestamptz not null default now()
);

create table if not exists public.projects (
  id uuid primary key default gen_random_uuid(),
  slug text not null unique,
  title text not null,
  category text not null,
  year text not null,
  description text not null,
  cover text not null,
  thumbnail text,
  client text,
  overview text,
  brief text,
  challenge text,
  approach text,
  process text[] not null default '{}',
  services text[] not null default '{}',
  palette jsonb not null default '[]',
  fonts jsonb not null default '[]',
  before_after_slug text,
  is_concept boolean not null default true,
  published boolean not null default true,
  sort_order integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.services (
  id uuid primary key default gen_random_uuid(),
  slug text not null unique,
  title text not null,
  description text not null,
  category text not null,
  sort_order integer not null default 0,
  published boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.before_after (
  id uuid primary key default gen_random_uuid(),
  slug text not null unique,
  title text not null,
  description text,
  before_image text not null,
  after_image text not null,
  before_label text not null default 'Before',
  after_label text not null default 'After',
  project_slug text,
  is_concept boolean not null default true,
  published boolean not null default true,
  sort_order integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.testimonials (
  id uuid primary key default gen_random_uuid(),
  quote text not null,
  name text not null,
  role text,
  company text,
  is_placeholder boolean not null default false,
  published boolean not null default true,
  sort_order integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.inquiries (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  email text not null,
  company text,
  service text,
  budget text,
  deadline text,
  message text not null,
  status text not null default 'new' check (status in ('new', 'read', 'replied', 'archived')),
  created_at timestamptz not null default now()
);

alter table public.projects enable row level security;

drop policy if exists "public read published projects" on public.projects;

create policy "public read published projects" on public.projects
    for select to anon, authenticated using (published = true);

drop policy if exists "admin manage projects" on public.projects;

create policy "admin manage projects" on public.projects
    for all to authenticated using (true) with check (true);

alter table public.services enable row level security;

drop policy if exists "public read published services" on public.services;

create policy "public read published services" on public.services
    for select to anon, authenticated using (published = true);

drop policy if exists "admin manage services" on public.services;

create policy "admin manage services" on public.services
    for all to authenticated using (true) with check (true);

alter table public.before_after enable row level security;

drop policy if exists "public read published before_after" on public.before_after;

create policy "public read published before_after" on public.before_after
    for select to anon, authenticated using (published = true);

drop policy if exists "admin manage before_after" on public.before_after;

create policy "admin manage before_after" on public.before_after
    for all to authenticated using (true) with check (true);

alter table public.testimonials enable row level security;

drop policy if exists "public read published testimonials" on public.testimonials;

create policy "public read published testimonials" on public.testimonials
    for select to anon, authenticated using (published = true);

drop policy if exists "admin manage testimonials" on public.testimonials;

create policy "admin manage testimonials" on public.testimonials
    for all to authenticated using (true) with check (true);

alter table public.site_settings enable row level security;

drop policy if exists "public read site settings" on public.site_settings;

create policy "public read site settings" on public.site_settings
  for select to anon, authenticated using (true);

drop policy if exists "admin manage site settings" on public.site_settings;

create policy "admin manage site settings" on public.site_settings
  for all to authenticated using (true) with check (true);

alter table public.inquiries enable row level security;

drop policy if exists "public insert inquiries" on public.inquiries;

create policy "public insert inquiries" on public.inquiries
  for insert to anon, authenticated with check (true);

drop policy if exists "admin read inquiries" on public.inquiries;

create policy "admin read inquiries" on public.inquiries
  for select to authenticated using (true);

drop policy if exists "admin update inquiries" on public.inquiries;

create policy "admin update inquiries" on public.inquiries
  for update to authenticated using (true) with check (true);

drop policy if exists "admin delete inquiries" on public.inquiries;

create policy "admin delete inquiries" on public.inquiries
  for delete to authenticated using (true);

insert into public.projects (slug, title, category, year, description, cover, thumbnail, client, overview, brief, challenge, approach, process, services, palette, fonts, before_after_slug, is_concept, published, sort_order, updated_at)
    values ('noir', 'NOIR', 'Brand Identity', '2026', 'A monochrome identity for a contemporary fashion label — built on contrast, negative space, and uncompromising typography.', '/work/noir-cover.jpg', '/work/noir-cover.jpg', 'Self-initiated (Concept)', 'NOIR is a concept identity for a contemporary fashion label that wanted to feel editorial rather than commercial. The system is built on a strict black-and-white palette, a high-contrast serif wordmark, and a layout grid that lets photography breathe. Every application — from woven labels to lookbook spreads — follows the same restrained visual logic.', 'Create a complete brand identity for a contemporary fashion label: wordmark, type system, color palette, stationery, and social templates. The brand should feel premium and editorial — never loud.', 'Fashion branding often mistakes decoration for luxury. The risk was producing something that would feel dated within a season; the identity had to be quiet, confident, and built to last.', 'I stripped the system to its essentials: one wordmark, two typefaces, a strict grid, and a single accent used sparingly. Photography is the hero — typography and layout stay out of its way.', ARRAY['Reference research — editorial fashion houses & lookbooks', 'Wordmark exploration — 40+ directions, 3 finalists', 'Type pairing & layout grid definition', 'Stationery, tags, and label applications', 'Brand guideline document & asset export']::text[], ARRAY['Logo Design & Brand Identity', 'Brand Guidelines & Visual Systems', 'Business Cards & Stationery']::text[], '[{"name":"Ink","hex":"#111111"},{"name":"Paper","hex":"#F7F5F0"},{"name":"Signal Lime","hex":"#D7FF64"},{"name":"Gray","hex":"#8A8A8A"}]'::jsonb, '[{"name":"Playfair Display","role":"Display serif — wordmark & headlines"},{"name":"Inter","role":"Body & UI text"}]'::jsonb, 'noir-logo', true, true, 0, now())
    on conflict (slug) do update set title = excluded.title, category = excluded.category, year = excluded.year, description = excluded.description, cover = excluded.cover, thumbnail = excluded.thumbnail, client = excluded.client, overview = excluded.overview, brief = excluded.brief, challenge = excluded.challenge, approach = excluded.approach, process = excluded.process, services = excluded.services, palette = excluded.palette, fonts = excluded.fonts, before_after_slug = excluded.before_after_slug, is_concept = excluded.is_concept, published = excluded.published, sort_order = excluded.sort_order, updated_at = now();

insert into public.projects (slug, title, category, year, description, cover, thumbnail, client, overview, brief, challenge, approach, process, services, palette, fonts, before_after_slug, is_concept, published, sort_order, updated_at)
    values ('fuel-lab', 'FUEL LAB', 'Packaging Design', '2025', 'High-voltage packaging for an energy drink — a can designed to be picked up from across the shelf.', '/work/fuellab-cover.jpg', '/work/fuellab-cover.jpg', 'Self-initiated (Concept)', 'FUEL LAB is a concept energy drink aimed at athletes and late-night creators. The packaging leans on a black base, an electric lime accent, and diagonal energy lines that wrap the can. The system works as a single can on a shelf or as a stacked retail display wall.', 'Design packaging for a new energy drink line: primary can, flavor color variants, and a retail display concept. Shelf impact from three meters away was the primary measure of success.', 'The energy drink aisle is a wall of noise — neon, explosions, and aggression everywhere. FUEL LAB needed to feel energetic without blending into the chaos.', 'One bold diagonal gesture, one electric accent, and disciplined typography. The can reads instantly at shelf distance and rewards a closer look with layered detail.', ARRAY['Category audit & shelf research', 'Concept directions — 3 visual territories', 'Can dieline & label system', 'Flavor variant color coding', 'Retail display & mockup renders']::text[], ARRAY['Packaging & Label Design', 'Product Mockups']::text[], '[{"name":"Black","hex":"#111111"},{"name":"Electric Lime","hex":"#D7FF64"},{"name":"White","hex":"#FFFFFF"},{"name":"Steel","hex":"#8A8A8A"}]'::jsonb, '[{"name":"Space Grotesk","role":"Display — can name & headlines"},{"name":"Inter","role":"Supporting text & nutrition panel"}]'::jsonb, null, true, true, 1, now())
    on conflict (slug) do update set title = excluded.title, category = excluded.category, year = excluded.year, description = excluded.description, cover = excluded.cover, thumbnail = excluded.thumbnail, client = excluded.client, overview = excluded.overview, brief = excluded.brief, challenge = excluded.challenge, approach = excluded.approach, process = excluded.process, services = excluded.services, palette = excluded.palette, fonts = excluded.fonts, before_after_slug = excluded.before_after_slug, is_concept = excluded.is_concept, published = excluded.published, sort_order = excluded.sort_order, updated_at = now();

insert into public.projects (slug, title, category, year, description, cover, thumbnail, client, overview, brief, challenge, approach, process, services, palette, fonts, before_after_slug, is_concept, published, sort_order, updated_at)
    values ('form', 'FORM', 'Campaign Design', '2025', 'A fitness campaign built on raw photography, condensed type, and one unmissable accent.', '/work/form-cover.jpg', '/work/form-cover.jpg', 'Self-initiated (Concept)', 'FORM is a concept launch campaign for an independent fitness studio. The visual language pairs documentary-style gym photography with condensed uppercase typography and a strict grid. Every asset — poster, story, or web banner — ends in the same place: a single, unmissable call to action.', 'Design a launch campaign for a new fitness studio: posters, social assets, and web banners. The tone should motivate without shouting — intense, not aggressive.', 'Fitness advertising defaults to volume. The goal was intensity through restraint — letting the photography and the type carry the energy instead of decoration.', 'A strict two-column grid, condensed uppercase type, and one electric accent per asset. The system flexes from A2 posters to 9:16 stories without losing its voice.', ARRAY['Audience & competitor campaign audit', 'Photography direction & art direction notes', 'Poster & social template system', 'Web banner adaptions', 'Campaign rollout kit & asset export']::text[], ARRAY['Poster & Flyer Design', 'Social Media Posts & Campaigns', 'Website Banners & Digital Ads']::text[], '[{"name":"Ink","hex":"#111111"},{"name":"Paper","hex":"#F7F5F0"},{"name":"Signal Lime","hex":"#D7FF64"}]'::jsonb, '[{"name":"Oswald","role":"Condensed display — headlines"},{"name":"Inter","role":"Supporting text & CTA"}]'::jsonb, null, true, true, 2, now())
    on conflict (slug) do update set title = excluded.title, category = excluded.category, year = excluded.year, description = excluded.description, cover = excluded.cover, thumbnail = excluded.thumbnail, client = excluded.client, overview = excluded.overview, brief = excluded.brief, challenge = excluded.challenge, approach = excluded.approach, process = excluded.process, services = excluded.services, palette = excluded.palette, fonts = excluded.fonts, before_after_slug = excluded.before_after_slug, is_concept = excluded.is_concept, published = excluded.published, sort_order = excluded.sort_order, updated_at = now();

insert into public.projects (slug, title, category, year, description, cover, thumbnail, client, overview, brief, challenge, approach, process, services, palette, fonts, before_after_slug, is_concept, published, sort_order, updated_at)
    values ('mono', 'MONO', 'Brand Identity', '2024', 'A quiet, confident identity for a specialty coffee roaster — kraft, cream, and typography doing all the talking.', '/work/mono-cover.jpg', '/work/mono-cover.jpg', 'Self-initiated (Concept)', 'MONO is a concept brand for a specialty coffee roaster that believes less is more. The identity pairs unbleached kraft textures with a precise typographic system: one typeface family, two colors, zero ornament. Bags, cups, menus, and the storefront all speak the same quiet language.', 'Brand a specialty coffee roastery: logo, packaging, cups, and storefront signage. The brand should feel artisanal but precise — handmade, never messy.', 'Artisanal coffee branding swings between twee and generic. MONO needed warmth with discipline — crafted, but controlled.', 'A characterful grotesque wordmark, a strict label grid, and kraft paper as the primary brand material. Color is earned, not sprayed.', ARRAY['Roastery positioning & audience research', 'Wordmark & monogram development', 'Packaging dielines & label grid', 'Cups, menus & signage applications', 'Brand book & print-ready exports']::text[], ARRAY['Logo Design & Brand Identity', 'Packaging & Label Design', 'Menu & Restaurant Graphics']::text[], '[{"name":"Kraft","hex":"#C9A87C"},{"name":"Cream","hex":"#F7F5F0"},{"name":"Espresso","hex":"#221A12"},{"name":"Ink","hex":"#111111"}]'::jsonb, '[{"name":"Space Grotesk","role":"Wordmark & headlines"},{"name":"Inter","role":"Body & labels"}]'::jsonb, 'mono-packaging', true, true, 3, now())
    on conflict (slug) do update set title = excluded.title, category = excluded.category, year = excluded.year, description = excluded.description, cover = excluded.cover, thumbnail = excluded.thumbnail, client = excluded.client, overview = excluded.overview, brief = excluded.brief, challenge = excluded.challenge, approach = excluded.approach, process = excluded.process, services = excluded.services, palette = excluded.palette, fonts = excluded.fonts, before_after_slug = excluded.before_after_slug, is_concept = excluded.is_concept, published = excluded.published, sort_order = excluded.sort_order, updated_at = now();

insert into public.projects (slug, title, category, year, description, cover, thumbnail, client, overview, brief, challenge, approach, process, services, palette, fonts, before_after_slug, is_concept, published, sort_order, updated_at)
    values ('culture', 'CULTURE', 'Poster Design', '2026', 'A festival poster series designed to be collected — loud type, louder color, wheatpaste-ready.', '/work/culture-cover.jpg', '/work/culture-cover.jpg', 'Self-initiated (Concept)', 'CULTURE is a concept poster series for a three-day music and arts festival. Each poster isolates one act, one color, and one typographic gesture. Together they form a wall; apart, each one stands on its own. The series extends into social cutdowns and a stage-screen loop.', 'Design a poster series for a music festival: A2 print posters, social cutdowns, and a stage-screen loop. The series must work as individual posters and as a collective wall.', 'Festival posters compete with each other on the same wall. The system had to be flexible enough for variety, strict enough for recognition.', 'A fixed grid, a rotating accent color, and type that scales from whisper to shout. Every poster shares the same bones; every act gets its own voice.', ARRAY['Festival identity & lineup research', 'Poster grid & type system', 'Per-act color & composition variants', 'Social & stage-screen adaptions', 'Print-ready exports & paste-up mockups']::text[], ARRAY['Poster & Flyer Design', 'Event & Music Posters', 'Motion Graphics & Animated Social Posts']::text[], '[{"name":"Violet","hex":"#6C3BF4"},{"name":"Heat","hex":"#FF4D24"},{"name":"Paper","hex":"#F7F5F0"},{"name":"Ink","hex":"#111111"}]'::jsonb, '[{"name":"Anton","role":"Poster display type"},{"name":"Space Grotesk","role":"Supporting information"}]'::jsonb, 'culture-poster', true, true, 4, now())
    on conflict (slug) do update set title = excluded.title, category = excluded.category, year = excluded.year, description = excluded.description, cover = excluded.cover, thumbnail = excluded.thumbnail, client = excluded.client, overview = excluded.overview, brief = excluded.brief, challenge = excluded.challenge, approach = excluded.approach, process = excluded.process, services = excluded.services, palette = excluded.palette, fonts = excluded.fonts, before_after_slug = excluded.before_after_slug, is_concept = excluded.is_concept, published = excluded.published, sort_order = excluded.sort_order, updated_at = now();

insert into public.projects (slug, title, category, year, description, cover, thumbnail, client, overview, brief, challenge, approach, process, services, palette, fonts, before_after_slug, is_concept, published, sort_order, updated_at)
    values ('nova', 'NOVA', 'Packaging Design', '2025', 'Soft, clinical, and quietly premium — skincare packaging that whispers luxury.', '/work/nova-cover.jpg', '/work/nova-cover.jpg', 'Self-initiated (Concept)', 'NOVA is a concept skincare line built on calm. The packaging system pairs soft pastel vessels with clean, clinical labels: monospaced ingredient data, generous whitespace, and a single serene serif for the brand voice. It feels closer to a lab than a candy store.', 'Design packaging for a three-product skincare line — cleanser, serum, moisturizer. The brand should feel clinical, calm, and premium, at a accessible price point.', 'The skincare shelf is a wall of pastel clichés. NOVA needed to feel scientific and serene at the same time — premium without pretension.', 'A restrained pastel system, structured data panels for ingredients, and one serif carrying the brand voice. Structure over ornament.', ARRAY['Category & competitor packaging audit', 'Structural form & material selection', 'Label grid & regulatory layout', 'Product photography direction', 'E-commerce & retail mockups']::text[], ARRAY['Packaging & Label Design', 'Product Mockups', 'E-commerce Product Graphics']::text[], '[{"name":"Blush","hex":"#F2D8D5"},{"name":"Cream","hex":"#F7F5F0"},{"name":"Sage","hex":"#B7C4B1"},{"name":"Ink","hex":"#111111"}]'::jsonb, '[{"name":"Cormorant Garamond","role":"Brand serif — product names"},{"name":"Inter","role":"Data, ingredients & labels"}]'::jsonb, null, true, true, 5, now())
    on conflict (slug) do update set title = excluded.title, category = excluded.category, year = excluded.year, description = excluded.description, cover = excluded.cover, thumbnail = excluded.thumbnail, client = excluded.client, overview = excluded.overview, brief = excluded.brief, challenge = excluded.challenge, approach = excluded.approach, process = excluded.process, services = excluded.services, palette = excluded.palette, fonts = excluded.fonts, before_after_slug = excluded.before_after_slug, is_concept = excluded.is_concept, published = excluded.published, sort_order = excluded.sort_order, updated_at = now();

insert into public.projects (slug, title, category, year, description, cover, thumbnail, client, overview, brief, challenge, approach, process, services, palette, fonts, before_after_slug, is_concept, published, sort_order, updated_at)
    values ('urban', 'URBAN', 'Campaign Design', '2024', 'A streetwear campaign shot on the street, for the street — raw photos, bold type, zero polish.', '/work/urban-cover.jpg', '/work/urban-cover.jpg', 'Self-initiated (Concept)', 'URBAN is a concept campaign for a streetwear label that wanted to feel found, not manufactured. Documentary street photography, a high-contrast grade, graffiti-adjacent typography, and layouts borrowed from zine culture. Wheatpaste posters, a lookbook, and a merch drop complete the rollout.', 'Launch a streetwear label with a campaign that feels authentic: street photography, poster takeovers, and a printed lookbook. No studio gloss.', 'Streetwear campaigns often over-produce. The brief asked for real streets, real light, and real texture — energy without a photo-studio sheen.', 'Documentary photography with a high-contrast editorial grade, type set like a wheatpaste poster, and layouts that borrow from zine culture.', ARRAY['Location scouting & casting', 'Photography direction & grade test', 'Poster & lookbook layout system', 'Merch graphics & drop assets', 'Campaign rollout kit']::text[], ARRAY['Poster & Flyer Design', 'Social Media Ad Creatives', 'T-Shirt & Merchandise Graphics']::text[], '[{"name":"Ink","hex":"#111111"},{"name":"Paper","hex":"#F7F5F0"},{"name":"Safety Orange","hex":"#FF5A1F"}]'::jsonb, '[{"name":"Archivo Black","role":"Display — campaign headlines"},{"name":"Space Grotesk","role":"Supporting text"}]'::jsonb, null, true, true, 6, now())
