insert into public.projects (slug, title, category, year, description, cover, thumbnail, client, overview, brief, challenge, approach, process, services, palette, fonts, before_after_slug, is_concept, published, sort_order, updated_at)
    values ('social-kit', 'SOCIAL KIT', 'Social Media Design', '2026', 'A 30-post social system for a product launch — one grid, endless variations, unmistakably one brand.', '/work/socialkit-cover.jpg', '/work/socialkit-cover.jpg', 'Self-initiated (Concept)', 'SOCIAL KIT is a concept content system for a product launch: a modular grid, three template families, and thirty ready-to-post designs. Announcements, education, and hype posts all draw from the same visual engine — so every post ships on time and still looks unmistakably on-brand.', 'Build a social media kit for a product launch: 30 square posts, 9 stories, and a highlight-cover set — all generated from one modular system.', 'Thirty posts can quietly become thirty one-offs. The system had to flex across announcements, education, and hype without losing its identity.', 'A strict grid, two type sizes, one accent color, and clear photography rules. Templates do the heavy lifting; the brand does the talking.', ARRAY['Platform & content audit', 'Modular grid & template families', '30-post content matrix', 'Story & highlight-cover adaptions', 'Editable template handover']::text[], ARRAY['Social Media Posts & Campaigns', 'Social Media Ad Creatives', 'Motion Graphics & Animated Social Posts']::text[], '[{"name":"Ink","hex":"#111111"},{"name":"Signal Lime","hex":"#D7FF64"},{"name":"Paper","hex":"#F7F5F0"},{"name":"White","hex":"#FFFFFF"}]'::jsonb, '[{"name":"Space Grotesk","role":"Headlines"},{"name":"Inter","role":"Body & captions"}]'::jsonb, 'social-post', true, true, 7, now())
    on conflict (slug) do update set title = excluded.title, category = excluded.category, year = excluded.year, description = excluded.description, cover = excluded.cover, thumbnail = excluded.thumbnail, client = excluded.client, overview = excluded.overview, brief = excluded.brief, challenge = excluded.challenge, approach = excluded.approach, process = excluded.process, services = excluded.services, palette = excluded.palette, fonts = excluded.fonts, before_after_slug = excluded.before_after_slug, is_concept = excluded.is_concept, published = excluded.published, sort_order = excluded.sort_order, updated_at = now();

insert into public.projects (slug, title, category, year, description, cover, thumbnail, client, overview, brief, challenge, approach, process, services, palette, fonts, before_after_slug, is_concept, published, sort_order, updated_at)
    values ('prime', 'PRIME', 'Brand Identity', '2024', 'A corporate identity with a spine — navy, gold, and a grid that means business.', '/work/prime-cover.jpg', '/work/prime-cover.jpg', 'Self-initiated (Concept)', 'PRIME is a concept identity for a corporate consultancy that needed to look established without looking old. A geometric monogram, a disciplined navy-and-gold system, and typography with a strong vertical rhythm — applied consistently across stationery, pitch decks, and signage.', 'Rebrand a corporate consultancy: identity, stationery, a pitch-deck template, and signage. Credible, confident, contemporary.', 'Corporate design defaults to safe. PRIME needed authority without arrogance — established, not elderly.', 'A geometric monogram, a disciplined two-color system, and typography with a strong vertical rhythm, applied with consistency across print and presentation.', ARRAY['Stakeholder interviews & positioning', 'Monogram & wordmark development', 'Stationery & collateral system', 'Pitch deck template design', 'Signage & environmental graphics']::text[], ARRAY['Logo Design & Brand Identity', 'Presentation & Pitch Deck Design', 'Business Cards & Stationery']::text[], '[{"name":"Navy","hex":"#14213D"},{"name":"Gold","hex":"#B08D2E"},{"name":"Paper","hex":"#F7F5F0"},{"name":"White","hex":"#FFFFFF"}]'::jsonb, '[{"name":"Source Serif 4","role":"Brand serif — headlines"},{"name":"Inter","role":"Corporate body text"}]'::jsonb, null, true, true, 8, now())
