insert into public.projects (slug, title, category, year, description, cover, thumbnail, client, overview, brief, challenge, approach, process, services, palette, fonts, before_after_slug, is_concept, published, sort_order, updated_at)
    values ('abstract', 'ABSTRACT', 'Typography', '2026', 'A self-initiated type experiment — deconstructed letterforms, printed large, judged by no one.', '/work/abstract-cover.jpg', '/work/abstract-cover.jpg', 'Self-initiated (Concept)', 'ABSTRACT is a self-initiated typography experiment: letterforms pulled apart, overlapped, and rebuilt as posters. No client, no brief — just type, ink, and paper. Ten treatments were explored; the strongest three were printed at A1 and pasted around the studio.', 'Personal experiment: push a single word through ten typographic treatments and print the strongest three as A1 posters.', 'With no client, the only audience is the work itself. Each treatment had to earn its place on the wall.', 'One word, ten treatments, strict black and white. Scale, overlap, and crop do the work that color usually fakes.', ARRAY['Word & letterform selection', 'Ten typographic treatments', 'A1 print & paste-up test', 'Final poster selection', 'Series documentation']::text[], ARRAY['Typography & Lettering']::text[], '[{"name":"Ink","hex":"#111111"},{"name":"Paper","hex":"#F7F5F0"},{"name":"White","hex":"#FFFFFF"}]'::jsonb, '[{"name":"Space Grotesk","role":"Experimental display"},{"name":"Inter","role":"Annotations"}]'::jsonb, null, true, true, 9, now())
