insert into public.testimonials (quote, name, role, company, is_placeholder, published, sort_order, updated_at)
    select '[PLACEHOLDER] Asim took a vague idea and returned a brand that felt like it had always existed. Replace this with a real client quote.', '[Client Name]', 'Founder', '[Company]', true, true, 0, now()
    where not exists (select 1 from public.testimonials where name = '[Client Name]' and quote = '[PLACEHOLDER] Asim took a vague idea and returned a brand that felt like it had always existed. Replace this with a real client quote.');

